    @SubscribeEvent public static void protectBreak(net.minecraftforge.event.level.BlockEvent.BreakEvent e){if(System.getProperty("thaumcraft.thaumaturgyProbe","").equals("bat-rift-client")&&(e.getPos().equals(protectBreak)||e.getPos().equals(stop)))e.setResult(net.minecraftforge.common.util.Result.DENY);}
    @SubscribeEvent public static boolean protectPlace(net.minecraftforge.event.level.BlockEvent.EntityPlaceEvent e){return System.getProperty("thaumcraft.thaumaturgyProbe","").equals("bat-rift-client")&&e.getPos().equals(protectPlace);}
